async function migrate() {
  requireConfigured();
  const db = getPool();
  const conn = await db.getConnection();
  try {
    await conn.beginTransaction();
    await conn.query(TABLES[0]);
    const [rows] = await conn.query('SELECT version FROM schema_migrations WHERE version = ?', [SCHEMA_VERSION]);
    if (!rows.length) {
      for (const statement of TABLES.slice(1)) await conn.query(statement);
      for (const statement of ACADEMIC_TABLES) await conn.query(statement);
      for (const statement of PART31_TABLES) await conn.query(statement);
      for (const role of ROLE_SEED) await conn.query('INSERT INTO roles (id, name, description) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE name = VALUES(name)', [`role_${role.toLowerCase()}`, role, `Canonical EduTrack role ${role}`]);
      for (const permission of PERMISSION_SEED) await conn.query('INSERT INTO permissions (id, name, description) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE name = VALUES(name)', [permission, permission, `EduTrack permission ${permission}`]);
      for (const [role, permissions] of Object.entries(ROLE_PERMISSION_SEED)) for (const permission of permissions) await conn.query('INSERT IGNORE INTO role_permissions (role_id, permission_id) VALUES (?, ?)', [`role_${role.toLowerCase()}`, permission]);
      await conn.query('ALTER TABLE teacher_attendance_records ADD COLUMN sign_in TIME NULL, ADD COLUMN sign_out TIME NULL').catch(() => {});
      await conn.query('ALTER TABLE schools ADD COLUMN school_code VARCHAR(120) NULL, ADD COLUMN ownership_type VARCHAR(32) NOT NULL DEFAULT \'PRIVATE\', ADD COLUMN address VARCHAR(255) NULL, ADD COLUMN contact_phone VARCHAR(80) NULL, ADD COLUMN contact_email VARCHAR(254) NULL, ADD COLUMN registration_metadata JSON NULL, ADD UNIQUE KEY schools_code_unique (school_code)').catch(() => {});
      await conn.query('INSERT INTO schema_migrations (version, name) VALUES (?, ?)', [SCHEMA_VERSION, 'part31-production-persistence-migration']);
    }
    await conn.commit();
  } catch (error) { await conn.rollback(); throw error; } finally { conn.release(); }
}
async function ensureInitialized() { if (!isConfigured()) return false; if (!initialized) initialized = migrate().catch((error) => { initialized = null; throw error; }); await initialized; return true; }

function rowToUser(row, credential) {
  if (!row) return null;
  return { id: row.id, email: row.email, staffId: row.staff_id, passwordHash: credential?.password_hash || '', accessCodeHash: credential?.access_code_hash || '', role: row.role_name || null, hierarchy: row.hierarchy, scope: parseJson(row.scope_json, null), active: Boolean(row.active), developmentFixture: Boolean(row.development_fixture), failedLoginCount: 0, lockedUntil: null, createdAt: row.created_at, updatedAt: row.updated_at };
}
async function findUser(identifier) {
  await ensureInitialized();
  const [rows] = await getPool().query(`SELECT u.*, c.password_hash, c.access_code_hash, r.name AS role_name, COALESCE(u.scope_json, tm.scope_json) AS scope_json FROM users u JOIN credentials c ON c.user_id = u.id LEFT JOIN user_roles ur ON ur.user_id = u.id LEFT JOIN roles r ON r.id = ur.role_id LEFT JOIN tenant_memberships tm ON tm.user_id = u.id AND tm.active = TRUE WHERE u.active = TRUE AND LOWER(u.email) = LOWER(?) LIMIT 1`, [identifier]);
  return rowToUser(rows[0], rows[0]);
}
async function findUserById(userId){await ensureInitialized();const [rows]=await getPool().query(`SELECT u.*, c.password_hash, c.access_code_hash, r.name AS role_name FROM users u JOIN credentials c ON c.user_id=u.id LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id WHERE u.id=? AND u.active=TRUE LIMIT 1`,[userId]);return rowToUser(rows[0],rows[0]);}
async function upsertUser(user) {
  await ensureInitialized();
  const now = iso(user.updatedAt || new Date()); const created = iso(user.createdAt || now);
  const db = getPool();
  await db.query(`INSERT INTO users (id,email,staff_id,status,active,development_fixture,hierarchy,scope_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE email=VALUES(email),staff_id=VALUES(staff_id),status=VALUES(status),active=VALUES(active),development_fixture=VALUES(development_fixture),hierarchy=VALUES(hierarchy),scope_json=VALUES(scope_json),updated_at=VALUES(updated_at)`, [user.id, user.email, user.staffId || null, user.active === false ? 'INACTIVE' : 'ACTIVE', user.active !== false, Boolean(user.developmentFixture), user.hierarchy || null, json(user.scope || null), created, now]);
  await db.query(`INSERT INTO credentials (id,user_id,password_hash,access_code_hash,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash),access_code_hash=VALUES(access_code_hash),status=VALUES(status),updated_at=VALUES(updated_at)`, [user.credentialId || newId('cred'), user.id, user.passwordHash, user.accessCodeHash || null, 'ACTIVE', created, now]);
  const role = user.role || 'DEVELOPER_ROOT';
  await db.query('INSERT INTO roles (id,name,description) VALUES (?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name)', [`role_${role.toLowerCase()}`, role, `Canonical EduTrack role ${role}`]);
  await db.query('INSERT INTO user_roles (user_id,role_id) VALUES (?,?) ON DUPLICATE KEY UPDATE role_id=VALUES(role_id)', [user.id, `role_${role.toLowerCase()}`]);
  return user;
}
