async function hydrateAuthState(db) {
  if (!isConfigured()) return db;
  await ensureInitialized();
  const [users] = await getPool().query(`SELECT u.*, c.password_hash, c.access_code_hash, r.name AS role_name FROM users u JOIN credentials c ON c.user_id=u.id LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id`);
  db.users = users.map((row) => rowToUser(row, row));
  const [sessions] = await getPool().query('SELECT id,token_hash AS tokenHash,user_id AS userId,created_at AS createdAt,expires_at AS expiresAt,revoked_at AS revokedAt,csrf_token_hash AS csrfTokenHash FROM server_sessions WHERE revoked_at IS NULL AND expires_at > CURRENT_TIMESTAMP');
  db.sessions = sessions;
  return db;
}
