  const [roles] = await getPool().query('SELECT r.name FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=?', [userId]);
  const [permissions] = await getPool().query('SELECT DISTINCT p.name FROM user_roles ur JOIN role_permissions rp ON rp.role_id=ur.role_id JOIN permissions p ON p.id=rp.permission_id WHERE ur.user_id=?', [userId]);
  const [memberships] = await getPool().query('SELECT tenant_id,scope_json,active FROM tenant_memberships WHERE user_id=?', [userId]);
  return { user: users[0], roles: roles.map((row) => row.name), permissions: permissions.map((row) => row.name), memberships: memberships.filter((row) => row.active).map((row) => ({ tenantId: row.tenant_id, scope: parseJson(row.scope_json, {}) })) };
